use std::{
    collections::HashMap,
    io,
    net::SocketAddr,
    sync::Arc,
};

use super::network::event_map::PatternLocation;
use crate::{
    log_err,
    mapping::{
        InputEventMessage, MapHandle,
        event::{Event, Frames, MaybeConst, Steps},
    },
};
